import unittest
from apps.local_tools.errors import ToolError


class TestToolError(unittest.TestCase):
    """Verify ToolError behavior with and without a code."""

    def test_default_code_is_none(self):
        err = ToolError("something went wrong")
        self.assertEqual(err.code, None)
        self.assertEqual(str(err), "something went wrong")

    def test_custom_code(self):
        err = ToolError("file missing", code="FILE_NOT_FOUND")
        self.assertEqual(err.code, "FILE_NOT_FOUND")
        self.assertEqual(str(err), "file missing")

    def test_is_runtime_error(self):
        with self.assertRaises(RuntimeError):
            raise ToolError("oops")

    def test_code_preserved_on_catch(self):
        try:
            raise ToolError("disk full", code="DISK_FULL")
        except ToolError as exc:
            self.assertEqual(exc.code, "DISK_FULL")


if __name__ == "__main__":
    unittest.main()

